={{ JSON.stringify({ model: 'deepseek/deepseek-chat', messages: [ { role: 'system', content: 'Voce e um auxiliar de manutencao industrial. Responda APENAS com um objeto JSON valido (sem markdown, sem cercas, sem texto fora) com duas chaves:

"resumo" = uma STRING (texto simples, NUNCA um array) com a descricao reescrita em portugues simples, corrigindo SO ortografia e gramatica, em topicos curtos separados por quebra de linha (cada topico comecando com - ). Vocabulario simples de pessoa da manutencao, sem palavras rebuscadas, sem inventar dados ausentes.

"recomendacoes" = array de 2 a 5 strings curtas e simples em portugues, so as que fizerem sentido, usando quando aplicavel: voltar ao equipamento em funcionamento para conferir vazamentos; com equipamento operando ler os medidores (pressao, vazao, temperatura); repor estoque das pecas usadas; anotar o horimetro para a proxima manutencao.' }, { role: 'user', content: $json.body.texto || '' } ], max_tokens: 700, temperature: 0.4 }) }}

parameters.jsCode:
const r = $input.first().json;
let content = (r?.choices?.[0]?.message?.content || '').trim();
if (!content) throw new Error('IA sem resposta');
content = content.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/,'').trim();
const m = content.match(/\{[\s\S]*\}/);
if (m) content = m[0];
let out = { resumo: '', recomendacoes: [] };
try {
  const p = JSON.parse(content);
  if (Array.isArray(p.resumo)) out.resumo = p.resumo.filter((x) => typeof x === 'string').map((x) => x.trim()).filter(Boolean).join('\n');
  else if (typeof p.resumo === 'string') out.resumo = p.resumo.trim();
  out.recomendacoes = Array.isArray(p.recomendacoes) ? p.recomendacoes.filter((x) => typeof x === 'string' && x.trim()).map((x) => x.trim()) : [];
} catch (e) { out.resumo = content; }
if (!out.resumo) throw new Error('IA sem resposta');
return out;
